        .signature-pad {
          position: relative;
          display: -webkit-box;
          display: -ms-flexbox;
          display: flex;
          -webkit-box-orient: vertical;
          -webkit-box-direction: normal;
          -ms-flex-direction: column;
          flex-direction: column;
          font-size: 10px;
          width: 100%;
          height: 250px;
          max-width: 950px;
          max-height: 460px;
          border: 1px solid var(--grey-color-tone-six);
          background-color: var(--white-color);
          box-shadow: 0 1px 4px rgb(0 0 0 / .27), 0 0 40px rgb(0 0 0 / .08) inset;
          border-radius: 4px;
          padding: 16px
        }

        .signature-pad::before,
        .signature-pad::after {
          position: absolute;
          z-index: -1;
          content: "";
          width: 40%;
          height: 10px;
          bottom: 10px;
          background: #fff0;
          box-shadow: 0 8px 12px rgb(0 0 0 / .4)
        }

        .signature-pad::before {
          left: 20px;
          -webkit-transform: skew(-3deg) rotate(-3deg);
          transform: skew(-3deg) rotate(-3deg)
        }

        .signature-pad::after {
          right: 20px;
          -webkit-transform: skew(3deg) rotate(3deg);
          transform: skew(3deg) rotate(3deg)
        }

        .signature-pad--body {
          position: relative;
          -webkit-box-flex: 1;
          -ms-flex: 1;
          flex: 1;
          border: 1px solid var(--grey-color-tone-eight)
        }

        .signature-pad--body canvas {
          position: absolute;
          left: 0;
          top: 0;
          width: 100%;
          height: 100%;
          border-radius: 4px
        }

        .signature-pad--footer {
          color: var(--grey-color-tone-five);
          text-align: center;
          font-size: 1.2em;
          margin-top: 8px
        }

        .signature-pad--actions {
