          --iti-arrow-padding: 6px;
          --iti-arrow-color: #555;
          --iti-path-flags-1x: url(https://static.mobilesentrix.com/skin/frontend/msentrix2022/default/css/images/allcountry-flags-sprites.svg?ver=1.0);
