          --iti-path-globe-2x: url(https://static.mobilesentrix.com/skin/frontend/msentrix2022/default/css/images/globe@2x.webp);
          --iti-flag-sprite-width: 5200px;
          --iti-flag-sprite-height: 20px;
          --iti-mobile-popup-margin: 30px;
          --iti-path-flags-2sprite-1x: url(https://static.mobilesentrix.com/skin/frontend/msentrix2022/default/css/images/fourcountry-sprites.svg);
          --iti-flag-sprite2-width: 80px
        }

        .iti {
          position: relative;
          display: inline-block
        }

        .iti * {
          box-sizing: border-box
        }

        .iti__hide {
          display: none
        }

        .iti__v-hide {
          visibility: hidden
        }

        .iti__a11y-text {
          width: 1px;
          height: 1px;
          clip: rect(1px, 1px, 1px, 1px);
          overflow: hidden;
          position: absolute
        }

        .iti input.iti__tel-input,
        .iti input.iti__tel-input[type=text],
        .iti input.iti__tel-input[type=tel] {
          position: relative;
          z-index: 0;
          margin: 0 !important
        }

        .iti__country-container {
          position: absolute;
          top: 0;
          bottom: 0;
          padding: var(--iti-border-width)
        }

        .iti__selected-country {
          z-index: 1;
          position: relative;
          display: flex;
          align-items: center;
          height: auto;
          background: none;
          border: 0;
          margin: 10px 0 0 0;
          padding: 0;
          font-family: inherit;
          font-size: inherit;
          color: inherit;
          border-radius: 0;
          font-weight: inherit;
          line-height: inherit;
          text-decoration: none
        }

        .iti__selected-country-primary {
          display: flex;
          align-items: center;
          height: 100%;
          padding: 0 var(--iti-arrow-padding) 0 var(--iti-spacer-horizontal)
        }

        .iti__arrow {
          margin-left: var(--iti-arrow-padding);
          width: 0;
          height: 0;
          border-left: var(--iti-triangle-border) solid #fff0;
          border-right: var(--iti-triangle-border) solid #fff0;
          border-top: var(--iti-arrow-height) solid var(--iti-arrow-color)
        }

        [dir=rtl] .iti__arrow {
          margin-right: var(--iti-arrow-padding);
          margin-left: 0
        }

        .iti__arrow--up {
          border-top: none;
          border-bottom: var(--iti-arrow-height) solid var(--iti-arrow-color)
        }

        .iti__dropdown-content {
          border-radius: 3px;
          background-color: var(--iti-dropdown-bg)
        }

        .iti--inline-dropdown .iti__dropdown-content {
          position: absolute;
          z-index: 2;
          margin-top: 3px;
          margin-left: calc(var(--iti-border-width) * -1);
          border: var(--iti-border-width) solid var(--iti-border-color);
          box-shadow: 1px 1px 4px rgb(0 0 0 / .2)
        }

        .iti__search-input {
          width: 100%;
          border-width: 0;
          border-radius: 3px
        }

        .iti__search-input+.iti__country-list {
          border-top: 1px solid var(--iti-border-color)
        }

        .iti__country-list {
          list-style: none;
          padding: 0;
          margin: 0;
          overflow-y: scroll;
          -webkit-overflow-scrolling: touch
        }

        .iti--inline-dropdown .iti__country-list {
          max-height: 185px
        }

        .iti--flexible-dropdown-width .iti__country-list {
          white-space: nowrap
        }

        @media (max-width:500px) {
          .iti--flexible-dropdown-width .iti__country-list {
            white-space: normal
          }
        }

        .iti__country {
          display: flex;
          align-items: center;
          padding: 8px var(--iti-spacer-horizontal);
          outline: none
